#define main legacy_main
#include "../spm-cuda/main.cu"
#undef main
#include <vector>
#include <fstream>
#include <iostream>
#include <iomanip>
#include <tuple>
struct Case{int v,n,size,mode;std::vector<float>M;std::vector<unsigned char>g,f,ra,rc,rt;float*m;unsigned char *gd,*fd,*a,*c;bool*t;};
int main(){std::vector<Case>cases;std::vector<float>prefix;for(int v:{17,33})for(int mode:{0,1}){Case c;c.v=v;c.mode=mode;c.n=v*v*v;c.size=(v+1)*(v+1)*(v+5);c.M.assign(16,0);c.M[0]=c.M[5]=c.M[10]=c.M[15]=1;if(mode){c.M[12]=.25f;c.M[13]=.5f;c.M[14]=.125f;}c.g.resize(c.size);c.f.resize(c.size);for(int i=0;i<c.size;i++){c.g[i]=(i*17+i/v*7)%251;c.f[i]=(i*29+i/(v*v)*13)%251;}c.ra.resize(c.n);c.rc.resize(c.n);c.rt.resize(c.n);bool*ref=new bool[c.n];spm_reference(c.M.data(),c.n,c.g.data(),c.f.data(),make_int3(v,v,v),make_int3(v,v,v),c.ra.data(),c.rc.data(),ref);for(int i=0;i<c.n;i++)c.rt[i]=ref[i];delete[]ref;cudaMalloc(&c.m,64);cudaMalloc(&c.gd,c.size);cudaMalloc(&c.fd,c.size);cudaMalloc(&c.a,c.n);cudaMalloc(&c.c,c.n);cudaMalloc(&c.t,c.n);cudaMemcpy(c.m,c.M.data(),64,cudaMemcpyHostToDevice);cudaMemcpy(c.gd,c.g.data(),c.size,cudaMemcpyHostToDevice);cudaMemcpy(c.fd,c.f.data(),c.size,cudaMemcpyHostToDevice);for(int x:{v,mode,c.n,c.size,3})prefix.push_back(x);prefix.insert(prefix.end(),c.M.begin(),c.M.end());for(auto x:c.g)prefix.push_back(x);for(auto x:c.f)prefix.push_back(x);cases.push_back(c);}
auto run=[&](Case&c,std::vector<float>&out){cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int rep=0;rep<3;rep++)spm<<<256,128>>>(c.m,c.n,c.gd,c.fd,make_int3(c.v,c.v,c.v),make_int3(c.v,c.v,c.v),c.a,c.c,c.t);cudaDeviceSynchronize();double time=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/3;std::vector<unsigned char>a(c.n),b(c.n),t(c.n);cudaMemcpy(a.data(),c.a,c.n,cudaMemcpyDeviceToHost);cudaMemcpy(b.data(),c.c,c.n,cudaMemcpyDeviceToHost);cudaMemcpy(t.data(),c.t,c.n,cudaMemcpyDeviceToHost);int err=0;bool ok=cudaGetLastError()==cudaSuccess;for(int i=0;i<c.n;i++){err=std::max(err,abs(int(a[i])-int(c.ra[i])));err=std::max(err,abs(int(b[i])-int(c.rc[i])));ok&=t[i]==c.rt[i];}for(auto x:a)out.push_back(x);for(auto x:b)out.push_back(x);for(auto x:t)out.push_back(x);return std::make_tuple(time,ok&&err==0,err);};std::vector<float>tmp;for(auto&c:cases)run(c,tmp);for(int trial=1;trial<=5;trial++){auto out=prefix;double time=0;bool ok=true;int err=0;std::cout<<"STUDY_COMPONENT_SECONDS ";for(auto&c:cases){auto[t,pass,e]=run(c,out);time+=t;ok&=pass;err=std::max(err,e);std::cout<<std::setprecision(17)<<t<<",";}std::cout<<std::endl;std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*4);f.close();std::cout<<"STUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<time<<",\"correct\":"<<(ok?"true":"false")<<",\"checked_values\":"<<out.size()<<",\"max_abs_error\":"<<err<<",\"timing_region\":\"sum4_three_spm_kernel_means\",\"jit_excluded\":true,\"internal_repeats\":3,\"output_artifact\":{\"path\":\""<<path<<"\",\"dtype\":\"float32\",\"count\":"<<out.size()<<",\"byte_order\":\"little\"}}"<<std::endl;if(!ok)return 2;}}
